79	// recordVersion 是落盘记录格式的版本标记。
80	const recordVersion = "numeric-job-v1"
81	
82	// storedJob 是作业在内存中的完整状态，所有字段均由 Store.mu 保护。
83	type storedJob struct {
84		id           uint64
85		submitter    string
86		requestID    string
87		seed         int64
88		values       []int64
89		dependencies []uint64 // 有序直接上游作业号；空表示无依赖
90	
91		queuedAt   time.Time
92		startedAt  time.Time
93		finishedAt time.Time
94	
95		status        Status
96		failureReason string
97		blockerID     uint64
98	
99		// 成功后保存的有效输入与归档（与 succeeded 状态同一次原子写入）。
100		effectiveValues []int64
101		archive         *Archive
102	
103		// canceled 仅存于内存：运行中的作业收到取消/关闭请求后置位，
104		// 计算循环据此尽快中止；终态不会依赖它落盘（终态本身会持久化）。
105		canceled atomic.Bool
106	}
107	
108	// jobRecord 是 storedJob 的落盘 JSON 表示。成功状态与归档在同一记录内，
109	// 一次 temp-file + rename 原子写入，因此对外不会出现“成功却没有结果”。
110	type jobRecord struct {
111		Version string `json:"version"`
112	
113		ID        uint64 `json:"id"`
114		Submitter string `json:"submitter"`
115		RequestID string `json:"request_id"`
116		// IdentityRaw 仅在提交人或请求号含非法 UTF-8 字节时出现，按完整字节
117		// 保真恢复标识；合法 UTF-8（含 U+0000）时缺省，记录与旧格式一致。
118		IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
119		Seed          int64        `json:"seed"`
120		Values        []int64      `json:"values"`
121		HasDependency bool         `json:"has_dependency"`
122		DependencyID  uint64       `json:"dependency_id"`
123		// Dependencies 为有序直接上游作业号；旧格式记录无此字段，
124		// 恢复时由 HasDependency/DependencyID 推导。
125		Dependencies []uint64 `json:"dependencies,omitempty"`
126	
127		QueuedAt   time.Time `json:"queued_at"`
128		StartedAt  time.Time `json:"started_at,omitempty"`
129		FinishedAt time.Time `json:"finished_at,omitempty"`
130	
131		Status        Status `json:"status"`
132		FailureReason string `json:"failure_reason,omitempty"`
133		BlockerID     uint64 `json:"blocker_id,omitempty"`
134	
135		EffectiveValues []int64  `json:"effective_values,omitempty"`
136		Archive         *Archive `json:"archive,omitempty"`
137	}
138	
139	func jobFileName(id uint64) string {
140		return fmt.Sprintf("job-%020d.json", id)
141	}
142	
143	func (s *Store) jobPath(j *storedJob) string {
144		return filepath.Join(s.dir, jobFileName(j.id))
145	}
146	
147	func encodeRecord(j *storedJob) ([]byte, error) {
148		hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
149		r := jobRecord{
150			Version: recordVersion,
151	
152			ID:            j.id,
153			Submitter:     j.submitter,
154			RequestID:     j.requestID,
155			IdentityRaw:   rawIdentity(j.submitter, j.requestID),
156			Seed:          j.seed,
157			Values:        append([]int64(nil), j.values...),
158			HasDependency: hasDependency,
159			DependencyID:  dependencyID,
160			Dependencies:  append([]uint64(nil), j.dependencies...),
161	
162			QueuedAt:      j.queuedAt,
163			StartedAt:     j.startedAt,
164			FinishedAt:    j.finishedAt,
165			Status:        j.status,
166			FailureReason: j.failureReason,
167			BlockerID:     j.blockerID,
168	
169			EffectiveValues: append([]int64(nil), j.effectiveValues...),
170			Archive:         j.archive,
171		}
172		return json.MarshalIndent(&r, "", "  ")
173	}
174	
175	// persist 在已持锁的情况下原子写一条作业记录。
176	func (s *Store) persist(j *storedJob) error {
177		// 测试用故障注入点（生产代码中 persistFault 恒为 nil）。
178		if s.persistFault != nil {
179			if err := s.persistFault(j); err != nil {
180				return err
181			}
182		}
183		data, err := encodeRecord(j)
184		if err != nil {
185			return err
186		}
187		return writeFileAtomic(s.dir, jobFileName(j.id), data, 0o600)
188	}
189	
190	// writeFileAtomic 将 data 写入 dir/name：同目录临时文件 → fsync → rename
191	// → 目录 fsync，保证记录要么是旧内容要么是新内容，不会出现半条记录。
192	func writeFileAtomic(dir, name string, data []byte, perm os.FileMode) error {
193		tmp, err := os.CreateTemp(dir, ".tmp-"+name+".*")
194		if err != nil {
195			return err
196		}
197		tmpName := tmp.Name()
198		cleanup := true
199		defer func() {
200			if cleanup {
201				_ = os.Remove(tmpName)
202			}
203		}()
204	
205		if _, err := tmp.Write(data); err != nil {
206			_ = tmp.Close()
207			return err
208		}
209		if err := tmp.Sync(); err != nil {
210			_ = tmp.Close()
211			return err
212		}
213		if err := tmp.Close(); err != nil {
214			return err
215		}
216		if err := os.Chmod(tmpName, perm); err != nil {
217			return err
218		}
219		if err := os.Rename(tmpName, filepath.Join(dir, name)); err != nil {
220			return err
221		}
222		cleanup = false
223		syncDir(dir)
224		return nil
225	}
226	
227	// syncDir 对目录本身做一次 fsync，让新建项与 rename 在崩溃后仍然成立。
228	func syncDir(dir string) {
229		if d, err := os.Open(dir); err == nil {
230			_ = d.Sync()
231			_ = d.Close()
232		}
233	}
234	
235	// loadDir 扫描目录中的全部作业记录并重建内存索引。
236	//
237	// 恢复规则：
238	//   - 上次关闭时仍为 running 的作业标记为失败，原因是计算被中断；
239	//   - 成功记录缺少归档、校验值对不上，依赖列表重复引用同一直接上游作业号，
240	//     或直接上游作业号不小于本作业号（引用自己或后来作业，违反提交时的
241	//     先后关系规则），实际输入与原始参数或直接依赖数量不对应，或归档数值
242	//     结果与有效输入按计算规则应得的结果不符时，fail-closed 地标记为失败，
243	//     维持“成功必有完整归档”的不变量；
244	//   - 有依赖的成功记录还要求每个直接上游都存在、恢复后仍是带完整归档的
245	//     成功状态，且实际输入的追加部分逐项等于这些上游按保存的依赖顺序
246	//     排列的总和；上游不可用的同样改判为失败，其失败原因指出直接上游、
247	//     BlockerID 沿链条保留最初的根因（与运行中依赖失败同一规则）；
248	//     仅追加输入对不上而上游全部有效的属于本作业自身归档有误，BlockerID
249	//     保持 0。排队记录的依赖列表重复引用同一作业号，或引用作业号不小于
250	//     自己的作业（自己/后来作业），同样在恢复时直接判失败（BlockerID 为
251	//     0），不再等待或开始计算；排队记录的原始整数序列为空（缺省、null 或
252	//     空数组）也直接判失败（BlockerID 为 0）——提交时即拒绝空序列，恢复时
253	//     不能凭已有实际输入或成功上游的总和补出原始参数后继续计算。仍在排队
254	//     的其他作业在同一趟升序扫描中按既有依赖规则级联失败。
255	func loadDir(dir string) ([]*storedJob, uint64, error) {
256		entries, err := os.ReadDir(dir)
257		if err != nil {
258			return nil, 0, err
259		}
260		var jobs []*storedJob
261		var maxID uint64
262		for _, e := range entries {
263			name := e.Name()
264			if e.IsDir() {
265				continue
266			}
267			// 清理上一进程崩溃时可能残留的原子写临时文件。
268			if strings.HasPrefix(name, ".tmp-") {
269				_ = os.Remove(filepath.Join(dir, name))
270				continue
271			}
272			if !strings.HasPrefix(name, "job-") || !strings.HasSuffix(name, ".json") {
273				continue
274			}
275			path := filepath.Join(dir, name)
276			data, err := os.ReadFile(path)
277			if err != nil {
278				return nil, 0, err
279			}
280			var r jobRecord
281			if err := json.Unmarshal(data, &r); err != nil {
282				return nil, 0, fmt.Errorf("numeric: 记录 %s 损坏: %w", name, err)
283			}
284			if r.Version != recordVersion {
285				return nil, 0, fmt.Errorf("numeric: 记录 %s 版本不受支持: %s", name, r.Version)
286			}
287			// 提交人、请求号按完整字节恢复：含非法 UTF-8 字节时以
288			// identity_raw 兜底字段为准，普通文本（含 U+0000）与旧归档原样使用。
289			submitter, requestID, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
290			if err != nil {
291				return nil, 0, fmt.Errorf("numeric: 记录 %s 标识损坏: %w", name, err)
292			}
293			// 成功归档内嵌同一份标识，同样按其自身兜底字段恢复，保证顶层记录
294			// 与归档中的参数逐字节一致。
295			if r.Archive != nil {
296				aSub, aReq, aErr := resolveIdentity(r.Archive.Submitter, r.Archive.RequestID, r.Archive.IdentityRaw)
297				if aErr != nil {
298					return nil, 0, fmt.Errorf("numeric: 记录 %s 归档标识损坏: %w", name, aErr)
299				}
300				r.Archive.Submitter = aSub
301				r.Archive.RequestID = aReq
302			}
303			switch r.Status {
304			case StatusQueued, StatusRunning, StatusSucceeded, StatusFailed, StatusCanceled:
305			default:
306				return nil, 0, fmt.Errorf("numeric: 记录 %s 状态非法: %q", name, r.Status)
307			}
308			// 新格式记录直接给出有序依赖列表；旧格式记录只有单依赖字段，
309			// 恢复为只含一个作业号的列表（语义与提交时一致）。两类字段同时
310			// 出现时以非空列表为实际依赖，与提交、归档核对共用同一换算。
311			deps := normalizeDependencies(r.HasDependency, r.DependencyID, r.Dependencies)
312			j := &storedJob{
313				id:           r.ID,
314				submitter:    submitter,
315				requestID:    requestID,
316				seed:         r.Seed,
317				values:       append([]int64(nil), r.Values...),
318				dependencies: deps,
319	
320				queuedAt:   r.QueuedAt,
321				startedAt:  r.StartedAt,
322				finishedAt: r.FinishedAt,
323	
324				status:        r.Status,
325				failureReason: r.FailureReason,
326				blockerID:     r.BlockerID,
327	
328				effectiveValues: append([]int64(nil), r.EffectiveValues...),
329				archive:         r.Archive,
330			}
331			if j.status == StatusRunning {
332				failRestoredJob(dir, j, "计算被中断：归档上次关闭时作业仍在运行", 0)
333			}
334			if j.status == StatusSucceeded {
335				// 除完整性外，还必须满足三条独立的对应/复算规则：
336				//  0. 依赖列表自身合法，按以下顺序检查：
337				//     a. 同一直接上游作业号不能出现两次（相邻或隔着其他上游都算）。
338				//        这与提交时 validateDependencyShapeLocked 的唯一性要求一致；
339				//        旧版本或被改动的记录可能保存了重复引用，此时即使追加值、
340				//        总和、平方和、摘要、日志与校验值全部自洽，也不能当作合法
341				//        成功归档（重复引用会把同一上游总和追加两次）。
342				//     b. 每个直接上游作业号都必须严格小于本作业号。正常提交只能引用
343				//        已经存在的作业，作业号又按接受先后递增，所以引用自己或引用
344				//        后来作业都不可能通过提交校验；旧版本或被改动的记录可能保存
345				//        这种依赖，即使被引用作业确实存在且成功、本作业的追加值、总和、
346				//        平方和、摘要、日志与校验值全部自洽，也不能接受。已因重复
347				//        依赖判失败的记录保留重复失败说明，不再改写。
348				//     两项都属于本作业记录自身有误，在任何上游可用性核对之前判定，
349				//     BlockerID 为 0，不把被引用的有效上游判成失败。
350				//  1. 实际输入与原始参数、直接依赖数量逐项对应——原始序列非空且
351				//     按原次序完整出现在实际输入开头，总长度恰为原始长度加上直接
352				//     依赖数；摘要、日志、校验值只与“实际输入”绑定，换成另一份
353				//     序列（如 [-3,2] 冒充 [2,-3]）仍能全套自洽，只有按位置比对
354				//     原始参数与依赖数量才能识别。
355				//  2. 归档中的数值结果必须与实际输入按既有计算规则应得的结果一致：
356				//     日志、摘要与校验值都可能与错误数字自洽，只有按保存的实际
357				//     输入复算才能识别。
358				// 任一不符合都按损坏归档处理。第四条规则——追加部分逐项等于各
359				// 直接上游恢复后的总和——需要全部记录恢复完毕才能核对，
360				// 在排序后的第二趟扫描中执行。
361				var invalidReason string
362				if dupID, dup := duplicateDependency(j); dup {
363					invalidReason = duplicateDependencyReason(dupID)
364				} else if badID, bad := firstIllegalOrderingDependency(j); bad {
365					invalidReason = illegalOrderingDependencyReason(badID, j.id)
366				} else if !archiveIntact(j) {
367					invalidReason = "归档不完整或校验值不一致，成功结果不可用"
368				} else if !effectiveInputsCorrespond(j) {
369					invalidReason = "实际输入与原始参数或依赖数量不符，成功结果不可用"
370				} else if !archiveResultsValid(j) {
371					invalidReason = "归档数值结果与有效输入按计算规则应得的结果不符，成功结果不可用"
372				}
373				if invalidReason != "" {
374					// 归档自身校验不通过：属于本作业自身失败，不携带阻断根因。
375					failRestoredJob(dir, j, invalidReason, 0)
376				}
377			}
378			jobs = append(jobs, j)
379			if j.id > maxID {
380				maxID = j.id
381			}
382		}
383		// 恢复后的排列必须与关闭前的接受先后一致：作业号在接受时单调分配，
384		// 按作业号升序即提交先后。记录上的提交时间只用于时间范围过滤，
385		// 不参与排序——本机时钟回拨会让后接受的作业带有更早的时间，
386		// 按时间重排会改变已确定的先后关系（也会让上游作业号更大的
387		// 依赖链在单趟级联扫描中漏掉失败传播）。
388		sort.Slice(jobs, func(a, b int) bool {
389			return jobs[a].id < jobs[b].id
390		})
391		// 第二趟：按作业号升序单趟处理依赖失效。直接上游在提交时必须已存在，
392		// 上游作业号必然更小，因此每个作业被处理时其全部直接上游都已是本次恢复
393		// 确定的最终状态——上游被改判失败时携带的根因作业号可直接沿链条继承，
394		// 不会在每经过一个已归档的中间作业时重新起算。
395		//
396		// 两类作业遵守同一项归因规则（与正常运行中的依赖失败一致）：失败原因
397		// 指出当前作业的直接上游，BlockerID 沿链条保留最初使结果不可用的根因；
398		// 只有本作业自身归档有误（上游全部有效、仅保存的追加输入不符）时
399		// BlockerID 才保持 0。
400		//   - 带依赖的成功记录：追加部分与上游恢复后的结果逐项核对；
401		//   - 排队记录：先检查记录自身是否合法——依赖列表重复引用同一作业号、
402		//     引用作业号不小于自己的作业（自己或后来作业），或原始整数序列为空，
403		//     都属本作业自身有误，BlockerID 为 0，立即失败（重复检查最前，空序列
404		//     检查最后）；再按保存的依赖顺序选取最靠前的不可用上游（已失败/取消，
405		//     或记录缺失），立即级联失败，不再等待。
406		//
407		// 依赖列表自身不合法属于记录自身问题，先于一切上游可用性判断：即使被引用
408		// 的上游仍在排队或确实存在且成功，不合法记录也要立即失败；而等待该记录
409		// 结果的下游则按既有规则把它当作失败上游级联，根因就是这份记录自身。
410		byID := make(map[uint64]*storedJob, len(jobs))
411		for _, j := range jobs {
412			byID[j.id] = j
413		}
414		for _, j := range jobs {
415			if j.status == StatusQueued {
416				// 排队记录自身有误的三项检查先于一切上游可用性判断，对有无依赖的
417				// 记录同样适用（无依赖时前两项自然不命中）：
418				//  1. 依赖列表重复引用同一作业号：不能开始计算，也不能把同一上游
419				//     总和追加两次后继续。BlockerID 保持 0，不把被重复引用且原本
420				//     有效的上游改成失败。
421				//  2. 依赖先后关系不合法：直接上游作业号必须严格小于本作业号，
422				//     引用自己或后来作业即使被引用者存在且成功也不能接受，不能开始
423				//     计算或继续等待。排在重复检查之后，已因重复依赖判失败的记录
424				//     保留现有说明。
425				//  3. 原始整数序列为空（缺省、null 或空数组）：提交时即拒绝空序列，
426				//     恢复时遵守同一项输入要求——不能开始运行，也不能凭已有实际输入
427				//     或成功上游的总和补出原始参数。BlockerID 保持 0。空序列指没有
428				//     任何原始整数；[0]、[0,0] 等非空序列仍是合法输入，不按总和
429				//     是否为 0 判断。
430				if dupID, dup := duplicateDependency(j); dup {
431					failRestoredJob(dir, j, duplicateDependencyReason(dupID), 0)
432					continue
433				}
434				if badID, bad := firstIllegalOrderingDependency(j); bad {
435					failRestoredJob(dir, j, illegalOrderingDependencyReason(badID, j.id), 0)
436					continue
437				}
438				if len(j.values) == 0 {
439					failRestoredJob(dir, j, emptyOriginalValuesReason(), 0)
440					continue
441				}
442			}
443			if len(j.dependencies) == 0 {
444				continue
445			}
446			switch j.status {
447			case StatusSucceeded:
448				// 第一趟：按保存的依赖顺序找最靠前的不可用上游（记录缺失或恢复后
449				// 未保持带完整归档的成功状态）。
450				directID, dep, unavailable := pickBlockingUpstream(j, byID, restoredArchiveUpstreamBlocked)
451				if unavailable {
452					// 因直接上游结果失效而失败：根因沿该上游已有的阻断信息保留，
453					// 直接上游记录缺失时以缺失的作业号本身作为根因。
454					root := blockerRoot(dep, directID)
455					failRestoredJob(dir, j, blockedFailureReason(restoredArchiveHead(directID), dep, directID, root), root)
456					continue
457				}
458				// 第二趟：直接上游全部存在且有效，只是本作业保存的追加输入与上游
459				// 总和按位置对不上——属于本作业自身归档有误，不把有效上游判成
460				// 失败或归因给它，BlockerID 保持 0。
461				if _, detail, mismatch := firstAppendedMismatch(j, byID); mismatch {
462					failRestoredJob(dir, j, detail, 0)
463				}
464			case StatusQueued:
465				// 记录自身的三项检查已在上面完成；这里按保存的依赖顺序选取最靠前
466				// 的不可用上游，其他上游作业号更小或失败原因不同都不能改变这个选择。
467				directID, direct, blocked := pickBlockingUpstream(j, byID, restoredQueuedUpstreamBlocked)
468				if !blocked {
469					continue // 上游仍在排队等情况：继续等待，不挡住其他作业。
470				}
471				root := blockerRoot(direct, directID)
472				if direct == nil {
473					// 直接上游的记录在归档目录中缺失，其结果不可能再变为可用：
474					// 以缺失的作业号作为根因，并明确说明结果无法使用。
475					failRestoredJob(dir, j, blockedFailureReason(restoredMissingHead(directID), nil, directID, root), root)
476					continue
477				}
478				failRestoredJob(dir, j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
479			}
480		}
481		return jobs, maxID, nil
482	}
483	
484	// failRestoredJob 收拢重新打开归档时把恢复出的作业改判为失败的统一处理，
485	// 供六类恢复失败共用（调用顺序即各类判定的既有先后）：
486	//   - 上次关闭时仍在运行的作业：计算被中断（第一趟记录扫描）；
487	//   - 原标为成功、但归档完整性、依赖列表唯一性或先后关系、实际输入对应
488	//     关系或数值结果不符规则的作业：本作业自身归档校验失败（第一趟记录
489	//     扫描，BlockerID 恒 0；唯一性检查先于先后关系检查）；
490	//   - 排队记录的依赖列表重复引用同一作业号：本作业记录自身有误（第二趟升序
491	//     扫描，BlockerID 恒 0，先于上游可用性判断）；
492	//   - 排队记录引用作业号不小于自己的作业（自己/后来作业）：本作业记录自身
493	//     有误（第二趟升序扫描，BlockerID 恒 0，在重复检查之后、空序列检查与
494	//     上游可用性判断之前）；
495	//   - 排队记录的原始整数序列为空（缺省、null 或空数组）：本作业记录自身
496	//     有误（第二趟升序扫描，BlockerID 恒 0，在依赖列表自身合法性检查之后、
497	//     上游可用性判断之前）；
498	//   - 被不可用直接上游阻断的作业：成功记录复核与排队记录复查（第二趟升序扫描），
499	//     BlockerID 由调用方按 blocker.go 的归因规则给出。
500	//
501	// 处理内容与各处原先内联的步骤完全一致：置失败状态、失败原因与阻断根因；
502	// 已经有完成时间的记录保留该时间，只有没有完成时间的才补上当前时间；
503	// 清除成功归档与实际参与计算的输入，使按作业号读取与按提交人列举都不再返回
504	// 成功归档或实际输入；作业号、提交人、请求号、原始整数次序、种子、依赖次序
505	// 与已有开始时间均不在此改动。归档可正常写入时，变化经同一条记录的一次
506	// 原子替换写回磁盘，而不只停留在内存查询结果中；写入失败维持既有尽力而为
507	// 语义（不因恢复阶段的一次落盘失败让整个归档无法打开）。
508	func failRestoredJob(dir string, j *storedJob, reason string, blocker uint64) {
509		j.status = StatusFailed
510		j.failureReason = reason
511		j.blockerID = blocker
512		if j.finishedAt.IsZero() {
513			j.finishedAt = time.Now().UTC()
514		}
515		j.effectiveValues = nil
516		j.archive = nil
517		if data, err := encodeRecord(j); err == nil {
518			_ = writeFileAtomic(dir, jobFileName(j.id), data, 0o600)
519		}
520	}
521	
522	// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
523	func archiveIntact(j *storedJob) bool {
524		a := j.archive
525		if a == nil {
526			return false
527		}
528		// 归档中的原始参数必须与记录顶层字段一致。
529		wantHasDependency, wantDependencyID := legacyDependencyFields(j.dependencies)
530		if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
531			a.Seed != j.seed || a.HasDependency != wantHasDependency {
532			return false
533		}
534		if a.HasDependency && a.DependencyID != wantDependencyID {
535			return false
536		}
537		// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
538		// 由单依赖字段推导后再比较，与记录恢复、提交内容比较共用同一换算。
539		aDeps := normalizeDependencies(a.HasDependency, a.DependencyID, a.Dependencies)
540		if len(aDeps) != len(j.dependencies) {
541			return false
542		}
543		for i := range j.dependencies {
544			if aDeps[i] != j.dependencies[i] {
545				return false
546			}
547		}
548		if len(a.Values) != len(j.values) {
549			return false
550		}
551		for i := range j.values {
552			if a.Values[i] != j.values[i] {
553				return false
554			}
555		}
556		if len(j.effectiveValues) == 0 || len(a.EffectiveValues) != len(j.effectiveValues) {
557			return false
558		}
559		for i := range j.effectiveValues {
560			if j.effectiveValues[i] != a.EffectiveValues[i] {
561				return false
562			}
563		}
564		if a.InputsDigest != inputsDigestHex(j.effectiveValues, j.seed) {
565			return false
566		}
567		if a.ResultDigest != resultDigestHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
568			return false
569		}
570		if a.Log != buildLog(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares) {
571			return false
572		}
573		if a.Checksum != checksumHex(j.effectiveValues, j.seed, a.Sum, a.SumOfSquares, a.Log, a.ResultDigest) {
574			return false
575		}
576		return true
577	}
578	
579	// archiveResultsValid 按既有计算规则对归档保存的实际输入（effectiveValues，
580	// 已含按顺序追加的上游总和，不再追加）复算总和与平方和，归档中的数值结果
581	// 必须与复算结果完全一致。完整性检查只验证日志、摘要与校验值和所写数字
582	// 自洽，无法识别“数字本身写错但全套字段一致”的记录，因此这里以计算规则
583	// 为准。实际输入按规则会造成 int64 溢出时 ok 为 false，任何数值结果
584	// （包括回绕后的值）都不能作为有效成功结果保留。
585	//
586	// 调用前须已通过 archiveIntact（保证 archive 非空且有效输入非空）。
587	func archiveResultsValid(j *storedJob) bool {
588		a := j.archive
589		sum, sumSquares, _, ok := computeResult(j.effectiveValues, j.seed, nil)
590		if !ok {
591			return false
592		}
593		return a.Sum == sum && a.SumOfSquares == sumSquares
594	}
595	
596	// effectiveInputsCorrespond 校验成功记录中实际参与计算的输入与原始提交
597	// 参数、直接依赖数量之间的对应关系：
598	//   - 原始序列必须非空；
599	//   - 原始序列逐项、按原次序完整出现在实际输入的开头——负数、零与重复
600	//     整数一律按位置判断，不比较总和或平方和，也不忽略次序；
601	//   - 实际输入总长度必须恰好等于原始序列长度加直接依赖数量。无依赖时两份
602	//     序列必须完全相同；有单个或多个依赖时，原始部分之后只能保留每个直接
603	//     上游各占一个位置的追加部分，不能借依赖之名替换、截短原始部分，也不
604	//     能多出未记录的输入。
605	//
606	// 该规则防止把另一份输入的自洽结果挂在原始参数下：例如原始参数为 [2,-3]
607	// 而实际输入被换成 [-3,2] 时，总和与平方和不变，摘要、日志与校验值又只
608	// 绑定实际输入，全套字段仍会自洽，只有按位置比对原始参数并核对追加数量
609	// 才能识别。旧的单依赖记录恢复后依赖列表恰含一个作业号，按同一含义判断。
610	//
611	// 调用前须已通过 archiveIntact（保证 archive 非空、实际输入非空且归档内
612	// 副本与顶层一致）。
613	func effectiveInputsCorrespond(j *storedJob) bool {
614		n := len(j.values)
615		if n == 0 {
616			return false
617		}
618		if len(j.effectiveValues) != n+len(j.dependencies) {
619			return false
620		}
621		for i := 0; i < n; i++ {
622			if j.effectiveValues[i] != j.values[i] {
623				return false
624			}
625		}
626		return true
627	}
