198		if dup.archive.Sum != 21 || dup.archive.SumOfSquares != 143 {
199			t.Fatalf("dup result=%d,%d want 21,143", dup.archive.Sum, dup.archive.SumOfSquares)
200		}
201	
202		s, err := Open(dir)
203		if err != nil {
204			t.Fatal(err)
205		}
206		defer s.Close()
207	
208		assertDuplicateDependencyFailure(t, s, 3, 1)
209		for _, id := range []uint64{1, 2} {
210			g, _ := s.Get(id)
211			if g.Status != StatusSucceeded || g.Archive == nil {
212				t.Fatalf("valid upstream %d must stay succeeded: %s", id, g.Status)
213			}
214		}
215	}
216	
217	// 排队记录的依赖列表重复时，重开后直接失败，不能开始计算（无开始时间、
218	// 无归档与实际输入）；等待它的下游随之失败，根因为该重复记录自身。
