231		writeSyntheticRecord(t, dir, &storedJob{
232			id: 3, submitter: "a", requestID: "child",
233			values: []int64{20}, dependencies: []uint64{2},
234			queuedAt: base.Add(3 * time.Second),
235			status:   StatusQueued,
236		})
237	
238		s, err := Open(dir)
239		if err != nil {
240			t.Fatal(err)
241		}
242		defer s.Close()
243	
244		assertDuplicateDependencyFailure(t, s, 2, 1)
245		g2, _ := s.Get(2)
246		if !g2.StartedAt.IsZero() {
247			t.Fatalf("duplicated queued job must never start computing, started=%s", g2.StartedAt)
248		}
249	
250		child := waitStatus(t, s, 3, StatusFailed)
251		if child.BlockerID != 2 || !strings.Contains(child.FailureReason, "直接上游作业 2") {
