291	// 已经失败或取消的记录即使保存了重复依赖列表，也保留既有终态、原因与根因，
292	// 不被恢复阶段的唯一性检查改写。
293	func TestReopenDuplicateDependencyKeepsExistingTerminalRecords(t *testing.T) {
294		dir := t.TempDir()
295		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
296		syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
